//go:build integration

package fixtures

import (
	"os"
	"path/filepath"
	"testing"
)

// TestConfigPaths holds the generated configuration files for one test.
type TestConfigPaths struct {
	ConfigPath string
	RolePath   string
	EnvPath    string
	SoulPath   string
	SkillPath  string
	Workspace  string
}

// WriteTestConfig generates a minimal, isolated config set for integration
// tests. It points Postgres/Redis at the provided test database and the LLM at
// the provided mock base URL.
func WriteTestConfig(t testing.TB, db *TestDatabase, ws string, llmBaseURL string) *TestConfigPaths {
	t.Helper()
	dir := filepath.Join(ws, "config")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatalf("create config dir: %v", err)
	}

	paths := &TestConfigPaths{
		ConfigPath: filepath.Join(dir, "config.yaml"),
		RolePath:   filepath.Join(dir, "roles.yaml"),
		EnvPath:    filepath.Join(dir, ".env"),
		SoulPath:   filepath.Join(dir, "soul.md"),
		SkillPath:  filepath.Join(dir, "skills.yaml"),
		Workspace:  ws,
	}

	writeFile(t, paths.ConfigPath, renderConfig(db.PostgresDSN, db.RedisAddr, db.RedisPass, db.RedisDB))
	writeFile(t, paths.RolePath, renderRoles())
	writeFile(t, paths.EnvPath, renderEnv(llmBaseURL))
	writeFile(t, paths.SoulPath, renderSoul())
	writeFile(t, paths.SkillPath, renderSkills())

	return paths
}

func writeFile(t testing.TB, path string, data []byte) {
	t.Helper()
	if err := os.WriteFile(path, data, 0o644); err != nil {
		t.Fatalf("write %s: %v", path, err)
	}
}

func renderConfig(postgresDSN, redisAddr, redisPass string, redisDB int) []byte {
	return []byte(`# Generated by integration test fixtures
postgres:
  dsn: "` + postgresDSN + `"
  max_open_conns: 10
  max_idle_conns: 2
  conn_max_lifetime: 300

pgvector:
  enabled: true
  dimensions: 768
  index_type: ivfflat
  distance_metric: cosine

redis:
  addr: "` + redisAddr + `"
  password: "` + redisPass + `"
  db: ` + itoa(redisDB) + `
  pool_size: 5
  min_idle_conns: 1
  dial_timeout: 5000
  read_timeout: 3000
  write_timeout: 3000
  snapshot_ttl_days: 1

http:
  addr: ":0"
  read_timeout: 30
  write_timeout: 30

memory:
  write_batch_size: 10
  write_flush_interval: 1
  snapshot_interval: 60

agent:
  stall_steps: 30
  max_repeat_fingerprint: 3
  session_timeout_min: 5
  skill_set_size: 4
  tool_call_max_rounds: 4
  retry_count: 1
  retry_backoff_ms: 10
  llm_soft_timeout_sec: 10
  llm_hard_timeout_sec: 20
  context_window: 8000
  interrupt_enabled: false
  queue_inject_enabled: false
  human_clarify_enabled: false
  dag_enabled: false
  plan_enabled: false
  reflection_enabled: false
  human_clarify_timeout_sec: 10

logging:
  enabled: false
  dir: logs
`)
}

