func itoa(i int) string {
	if i == 0 {
		return "0"
	}
	var buf [20]byte
	neg := false
	if i < 0 {
		neg = true
		i = -i
	}
	n := 0
	for i > 0 {
		buf[n] = byte('0' + i%10)
		i /= 10
		n++
	}
	if neg {
		buf[n] = '-'
		n++
	}
	for i := 0; i < n/2; i++ {
		buf[i], buf[n-1-i] = buf[n-1-i], buf[i]
	}
	return string(buf[:n])
}
